-- Going to deep sleep: the glaz eye closes, for a second, so the
-- wearer knows the glasses are asleep and not just dark. Part of
-- frame_app.lua, in a file of its own, loaded only then. ASCII only.
-- Generated by flutter-glaz/tool/logo.py blink -- edit it there.
--
-- One character per pixel, one string per row, as sprites/logo.lua.

-- character -> palette index (the order of frame.display's colour table)
local COLORS = {
  ['.'] = 0,    -- VOID, transparent
  w = 1,        -- WHITE
  k = 2,        -- GREY
  r = 3,        -- RED
  d = 9,        -- DARKGREEN
  g = 10,       -- GREEN
  G = 11,       -- LIGHTGREEN
}

-- the eye, open
local EYE = {
  '...........kkkkrkkkkk...........',
  '........kkkwwwrwwwwwwkkk........',
  '.......kwwwwrrrwwwwwwwwwk.......',
  '......kwwrwwwddddddwwrwwwk......',
  '.....kwwrwwdddGGggdddwrwrwk.....',
  '....kwwrwwddgGGGgggGddrwrwwk....',
  '...kwwrwwwdgwwggggGGGdwrwwwwk...',
  '...wwwrwwddGww....gGgddrrwwww...',
  '..kwwrwwrdGGg......gggdrwrrwwk..',
  '..wwwrrrwdGGg......gggdrwwwrww..',
  '..wrrwwwrdggg......gGGdwrwwrrw..',
  '..wwrwwwrdggg.....wgGGdwrrrrww..',
  '...wwrrwwddgGg....ggGddrwwrww...',
  '...wwwwrrrdGGGgggggggdwrwwrww...',
  '....wwwwrrddGgggGGGgddrwwrww....',
  '.....wwwrrwdddggGGdddwrwwwr.....',
  '......wwwwrwwddddddwwwrwww......',
  '.......wwwwrwwwwwwwwwwrww.......',
  '........wwwrwwwwwwwrrrww........',
  '...........wrwwwwwwrw...........',
}

-- the eye, shut: its ends level with the middle of the open eye
local SHUT = {
  '..ww........................ww..',
  '....wwwww..............wwwww....',
  '......w..wwwwwwwwwwwwww..w......',
  '.....w.......w....w.......w.....',
  '............w......w............',
}

-- Scale and place: the eye in the middle of what the wearer sees, 640 wide
-- and 340 down (VISIBLE_BOTTOM in frame_app.lua).
local S = 8
local X = (640 - #EYE[1] * S) // 2
local Y = (340 - #EYE * S) // 2
local STEPS    = 6     -- frames from open to the lids meeting
local CLOSING  = 0.5   -- seconds they take
local DURATION = 1     -- seconds in all, closing and closed

-- Row n of the art, at row n of the eye. lid: what the row covers is drawn
-- GREY, the edge of a lid.
local function row(s, n, lid)
  local a, b = s:find('[^.].*[^.]')
  local t = {}
  for i = 1, #s do
    local c = COLORS[s:sub(i, i)]
    if lid and a and i >= a and i <= b then c = COLORS.k end
    t[i] = string.char(c * 17):rep(S // 2)
  end
  frame.display.bitmap(X, Y + (n - 1) * S, #s * S, 16, 0,
                       table.concat(t):rep(S))
end

local function wait(t)
  while frame.time.utc() < t do frame.sleep(0.01) end
end

-- show: frame_app.lua's, which flips the buffer and waits until it is free.
-- Takes DURATION, or longer if drawing is slow; ends with the eye shut on
-- screen, for the caller to blank.
return function(show)
  local t0 = frame.time.utc()
  local mid = (#EYE + 1) / 2
  for step = STEPS, 1, -1 do
    local half = mid * step / STEPS     -- rows still open, either side
    for n, s in ipairs(EYE) do
      local d = math.abs(n - mid)
      if d < half then row(s, n, d >= half - 1) end
    end
    show()
    collectgarbage('collect')
    wait(t0 + CLOSING * (STEPS - step + 1) / STEPS)
  end
  -- the lid sags two rows below its ends: they sit at the eye's middle
  for i, s in ipairs(SHUT) do row(s, math.floor(mid) + i - 3) end
  show()
  wait(t0 + DURATION)
end
